#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> numbers;
    int sum = 0;

    for (int i = 0; i < N; ++i) {
        int x;
        cin >> x;

        if (x == 0) {
            if (!numbers.empty()) {
                sum -= numbers.back();
                numbers.pop_back();
            }
        } else {
            numbers.push_back(x);
            sum += x;
        }
    }

    cout << sum << '\n';
    return 0;
}
